// renderGameAbilityValue renders any game.Ability implementation by switching on its concrete type.
//
// Every implementation in mtg/game has a case, so adding one and forgetting to
// teach the renderer about it is impossible: the case appears when this file
// is regenerated, and the generator fails if the value cannot be emitted.
func (r Renderer) renderGameAbilityValue(ctx *renderCtx, v game.Ability) (string, error) {
	if v == nil {
		return "", errors.New("render: nil game.Ability")
	}
	switch value := v.(type) {
	case *game.AbilityContent:
		if value == nil {
			return "", errors.New("render: nil *game.AbilityContent")
		}
		lit, err := r.renderGameAbilityContent(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.ActivatedAbility:
		if value == nil {
			return "", errors.New("render: nil *game.ActivatedAbility")
		}
		lit, err := r.renderGameActivatedAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.ChapterAbility:
		if value == nil {
			return "", errors.New("render: nil *game.ChapterAbility")
		}
		lit, err := r.renderGameChapterAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.LoyaltyAbility:
		if value == nil {
			return "", errors.New("render: nil *game.LoyaltyAbility")
		}
		lit, err := r.renderGameLoyaltyAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.ManaAbility:
		if value == nil {
			return "", errors.New("render: nil *game.ManaAbility")
		}
		lit, err := r.renderGameManaAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.ReplacementAbility:
		if value == nil {
			return "", errors.New("render: nil *game.ReplacementAbility")
		}
		lit, err := r.renderGameReplacementAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.StaticAbility:
		if value == nil {
			return "", errors.New("render: nil *game.StaticAbility")
		}
		lit, err := r.renderGameStaticAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	case *game.TriggeredAbility:
		if value == nil {
			return "", errors.New("render: nil *game.TriggeredAbility")
		}
		lit, err := r.renderGameTriggeredAbility(ctx, *value)
		if err != nil {
			return "", err
		}
		return "&" + lit, nil
	default:
		return "", fmt.Errorf("render: unhandled game.Ability: %T", v)
	}
}

